--

CREATE FUNCTION public.get_user_profiles_with_email() RETURNS TABLE(id uuid, full_name text, parent_name text, child_name text, role text, is_active boolean, created_at timestamp with time zone, updated_at timestamp with time zone, email text)
    LANGUAGE sql SECURITY DEFINER
