--
-- Name: get_working_days_in_month_with_holidays(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_working_days_in_month_with_holidays(year_val integer, month_val integer) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    working_days INTEGER := 0;
    curr_date DATE;
    end_date DATE;
    day_of_week INTEGER;
    is_holiday BOOLEAN;
BEGIN
    curr_date := DATE(year_val, month_val, 1);
    end_date := (DATE(year_val, month_val, 1) + INTERVAL '1 month' - INTERVAL '1 day')::DATE;
    
    WHILE curr_date <= end_date LOOP
        day_of_week := EXTRACT(DOW FROM curr_date);
        
        -- Check if day is Monday (1) to Friday (5)
        IF day_of_week BETWEEN 1 AND 5 THEN
            -- Check if it's a holiday
            -- Check for exact date match
            SELECT EXISTS(
                SELECT 1 FROM public.holidays 
                WHERE date = curr_date
            ) INTO is_holiday;
            
            -- If not found, check for recurring holidays (same month and day, any year)
            IF NOT is_holiday THEN
                SELECT EXISTS(
                    SELECT 1 FROM public.holidays 
                    WHERE is_recurring = true
                    AND EXTRACT(MONTH FROM date) = month_val
                    AND EXTRACT(DAY FROM date) = EXTRACT(DAY FROM curr_date)
                ) INTO is_holiday;
            END IF;
            
            -- If not a holiday, count as working day
            IF NOT is_holiday THEN
                working_days := working_days + 1;
            END IF;
        END IF;
        
        curr_date := curr_date + INTERVAL '1 day';
    END LOOP;
    
    RETURN working_days;
END;
$$;


--
-- Name: handle_new_user_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user_profile() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  has_owner boolean;
  profile_exists boolean;
BEGIN
  -- Проверяем, существует ли уже профиль (на случай race condition)
  SELECT EXISTS(SELECT 1 FROM public.user_profiles WHERE id = NEW.id) INTO profile_exists;
  
  IF profile_exists THEN
    -- Профиль уже существует, ничего не делаем
    RETURN NEW;
  END IF;

  -- Проверяем, существует ли уже owner в системе
  SELECT EXISTS(SELECT 1 FROM public.user_profiles WHERE role = 'owner') INTO has_owner;

  -- Пытаемся создать профиль
  BEGIN
    VALUES (
      NEW.id,
      -- Извлекаем имя из user_metadata
      COALESCE(
        NEW.raw_user_meta_data->>'parent_name',
        NEW.raw_user_meta_data->>'full_name', 
        NEW.raw_user_meta_data->>'name'
      ),
      NEW.raw_user_meta_data->>'parent_name',
      NEW.raw_user_meta_data->>'child_name',
      -- Только если нет owner, новый пользователь станет owner
      CASE WHEN NOT has_owner THEN 'owner' ELSE 'newregistration' END,
      -- Owner активен, остальные нет
      CASE WHEN NOT has_owner THEN true ELSE false END
    )
    ON CONFLICT (id) DO NOTHING;
    
    -- Логируем в PostgreSQL logs
    RAISE NOTICE 'Created user profile for user % with role % and metadata: parent_name=%, child_name=%', 
      NEW.id,
      CASE WHEN NOT has_owner THEN 'owner' ELSE 'newregistration' END,
      NEW.raw_user_meta_data->>'parent_name',
      NEW.raw_user_meta_data->>'child_name';
      
  EXCEPTION
    WHEN OTHERS THEN
      -- Логируем ошибку, но не прерываем создание пользователя
      RAISE WARNING 'Failed to create user profile for user %: %. Metadata: %', NEW.id, SQLERRM, NEW.raw_user_meta_data;
      -- Профиль будет создан позже через fetchOrCreateProfile в клиентском коде
      RETURN NEW;
  END;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION handle_new_user_profile(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.handle_new_user_profile() IS 'Автоматически создает профиль пользователя при регистрации. Первый пользователь в системе (определяется по отсутствию роли owner) получает роль owner и активируется автоматически. Остальные получают роль newregistration и требуют активации администратором.';


